+      }
+
+      .icon {
+        display: grid;
+        width: 34px;
+        height: 34px;
+        flex: 0 0 auto;
+        place-items: center;
+        border-radius: 50%;
+        color: #08111f;
+        background: linear-gradient(135deg, var(--accent), var(--accent-strong));
+        font-size: 1.25rem;
