        margin: 0;
        font-size: clamp(2.5rem, 7vw, 5rem);
        line-height: 1;
        letter-spacing: -0.06em;
      }

      .intro {
        max-width: 650px;
        margin: 18px auto 0;
        color: var(--muted);
        font-size: 1.08rem;
      }

      .faq-card {
        overflow: hidden;
        border: 1px solid rgba(255, 255, 255, 0.1);
        border-radius: 28px;
        background: rgba(17, 26, 47, 0.78);
        box-shadow: var(--shadow);
        backdrop-filter: blur(18px);
      }

      .example {
        border-top: 1px solid rgba(255, 255, 255, 0.09);
      }

      .example:first-child {
        border-top: 0;
      }

      .question {
        display: flex;
        width: 100%;
        align-items: center;
        justify-content: space-between;
        gap: 18px;
        padding: 24px 26px;
        border: 0;
        color: var(--text);
        background: transparent;
        font: inherit;
        font-size: 1.1rem;
        font-weight: 800;
        text-align: left;
        cursor: pointer;
      }

      .question:hover {
        background: rgba(255, 255, 255, 0.045);
      }

      .question:focus-visible {
        outline: 3px solid var(--ring);
        outline-offset: -5px;
      }

      .icon {
        display: grid;
        width: 34px;
        height: 34px;
        flex: 0 0 auto;
        place-items: center;
        border-radius: 50%;
        color: #08111f;
        background: linear-gradient(135deg, var(--accent), var(--accent-strong));
        font-size: 1.25rem;
        font-weight: 900;
        transition: transform 180ms ease;
      }

      .question[aria-expanded="true"] .icon {
        transform: rotate(45deg);
      }

      .details {
        display: none;
        padding: 0 26px 26px;
        color: var(--muted);
      }

      .details[aria-hidden="false"] {
        display: block;
      }

      .details p {
        max-width: 70ch;
        margin: 0;
      }

      @media (max-width: 640px) {
        .page {
          width: min(100% - 20px, 920px);
          padding: 36px 0;
        }

        .faq-card {
          border-radius: 20px;
        }

        .question {
          padding: 20px;
          font-size: 1rem;
        }

        .details {
          padding: 0 20px 22px;
        }
      }
    </style>
  </head>
  <body>
    <main class="page">
      <section class="hero" aria-labelledby="page-title">
        <p class="eyebrow">Cats, explained</p>
        <h1 id="page-title">Cat FAQ</h1>
        <p class="intro">
          Quick answers to common questions about cat behavior, care, and daily
          life with a curious feline companion.
        </p>
      </section>

      <section class="faq-card" aria-label="Frequently asked questions about cats">
        <div id="faq-root"></div>
      </section>
    </main>

    <script>
      const faqs = [
        {
          question: "Why do cats purr?",
          answer:
            "Cats often purr when they are relaxed or content, but purring can also be a self-soothing behavior when they are stressed, uncomfortable, or healing."
        },
        {
          question: "How much sleep do cats need?",
          answer:
            "Most adult cats sleep between 12 and 16 hours a day. Kittens and senior cats may sleep even more because growth, play, and aging all require extra rest."
        },
        {
          question: "Why does my cat knead blankets or my lap?",
          answer:
            "Kneading is a comforting behavior that begins in kittenhood. Adult cats may knead soft surfaces when they feel safe, affectionate, or ready to settle down."
        },
        {
          question: "Do indoor cats need enrichment?",
          answer:
            "Yes. Indoor cats benefit from climbing spaces, scratching posts, window views, puzzle feeders, and daily interactive play that lets them stalk, chase, and pounce."
        },
        {
          question: "How often should I clean the litter box?",
          answer:
            "Scoop the litter box at least once a day and fully refresh it on a regular schedule based on the litter type. A clean box supports good hygiene and helps prevent avoidance."
        }
      ];

      function FAQItem({ question, answer }, index) {
        const buttonId = `faq-question-${index}`;
        const detailsId = `faq-answer-${index}`;

        return `
          <div class="example">
            <h2>
              <button
                class="question"
                id="${buttonId}"
                type="button"
                aria-expanded="false"
                aria-controls="${detailsId}"
              >
                <span>${question}</span>
                <span class="icon" aria-hidden="true">+</span>
              </button>
            </h2>
            <div
              class="details"
              id="${detailsId}"
              role="region"
              aria-labelledby="${buttonId}"
              aria-hidden="true"
            >
              <p>${answer}</p>
            </div>
          </div>
        `;
      }

      function FAQPage({ items }) {
        return items.map(FAQItem).join("");
      }

      function hydrateFAQ(root) {
        root.addEventListener("click", (event) => {
          const button = event.target.closest(".question");

          if (!button) {
            return;
          }

          const details = document.getElementById(button.getAttribute("aria-controls"));
          const isExpanded = button.getAttribute("aria-expanded") === "true";

          button.setAttribute("aria-expanded", String(!isExpanded));
          details.setAttribute("aria-hidden", String(isExpanded));
        });
      }

      const root = document.getElementById("faq-root");
      root.innerHTML = FAQPage({ items: faqs });
      hydrateFAQ(root);
    </script>
  </body>
</html>
